CREATE TABLE `DirectMessage` (`id` VARCHAR(191) NOT NULL, `senderId` VARCHAR(191) NOT NULL, `recipientId` VARCHAR(191) NOT NULL, `body` TEXT NOT NULL, `readAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `DirectMessage_senderId_recipientId_createdAt_idx`(`senderId`, `recipientId`, `createdAt`), INDEX `DirectMessage_recipientId_readAt_idx`(`recipientId`, `readAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `FeedPost` (`id` VARCHAR(191) NOT NULL, `authorId` VARCHAR(191) NOT NULL, `body` TEXT NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, INDEX `FeedPost_createdAt_idx`(`createdAt`), INDEX `FeedPost_authorId_createdAt_idx`(`authorId`, `createdAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `FeedLike` (`id` VARCHAR(191) NOT NULL, `postId` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `FeedLike_postId_userId_key`(`postId`, `userId`), INDEX `FeedLike_userId_idx`(`userId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `FeedComment` (`id` VARCHAR(191) NOT NULL, `postId` VARCHAR(191) NOT NULL, `authorId` VARCHAR(191) NOT NULL, `body` TEXT NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `FeedComment_postId_createdAt_idx`(`postId`, `createdAt`), INDEX `FeedComment_authorId_idx`(`authorId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `DirectMessage` ADD CONSTRAINT `DirectMessage_senderId_fkey` FOREIGN KEY (`senderId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `DirectMessage` ADD CONSTRAINT `DirectMessage_recipientId_fkey` FOREIGN KEY (`recipientId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `FeedPost` ADD CONSTRAINT `FeedPost_authorId_fkey` FOREIGN KEY (`authorId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `FeedLike` ADD CONSTRAINT `FeedLike_postId_fkey` FOREIGN KEY (`postId`) REFERENCES `FeedPost`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `FeedLike` ADD CONSTRAINT `FeedLike_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `FeedComment` ADD CONSTRAINT `FeedComment_postId_fkey` FOREIGN KEY (`postId`) REFERENCES `FeedPost`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `FeedComment` ADD CONSTRAINT `FeedComment_authorId_fkey` FOREIGN KEY (`authorId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
